I'll create a simple test API using Node.js and run it for you.

First, let me check if Node.js is available and set up the project.

```bash
node --version && npm --version
```

Now I'll create a simple Express-based REST API.

```bash
mkdir -p /home/jack/Coding/Rust/cuttlefish-rs/test-api && cd /home/jack/Coding/Rust/cuttlefish-rs/test-api && npm init -y
```

```bash
cd /home/jack/Coding/Rust/cuttlefish-rs/test-api && npm install express
```

Now I'll create the API server:

```typescript
const express = require('express');
const app = express();
const PORT = 3000;

app.use(express.json());

// In-memory data store
let items = [
  { id: 1, name: 'Item One', description: 'First test item' },
  { id: 2, name: 'Item Two', description: 'Second test item' },
];

// GET - Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET - List all items
app.get('/api/items', (req, res) => {
  res.json({ items, count: items.length });
});

// GET - Get single item by ID
app.get('/api/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const item = items.find(i => i.id === id);

  if (!item) {
    return res.status(404).json({ error: 'Item not found' });
  }
  res.json(item);
});

// POST - Create new item
app.post('/api/items', (req, res) => {
  const { name, description } = req.body;

  if (!name) {
    return res.status(400).json({ error: 'Name is required' });
  }

  const newItem = {
    id: items.length > 0 ? Math.max(...items.map(i => i.id)) + 1 : 1,
    name,
    description: description || '',
  };

  items.push(newItem);
  res.status(201).json(newItem);
});

// PUT - Update item
app.put('/api/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const index = items.findIndex(i => i.id === id);

  if (index === -1) {
    return res.status(404).json({ error: 'Item not found' });
  }

  const { name, description } = req.body;
  items[index] = { ...items[index], name: name || items[index].name, description: description ?? items[index].description };
  res.json(items[index]);
});

// DELETE - Remove item
app.delete('/api/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const index = items.findIndex(i => i.id === id);

  if (index === -1) {
    return res.status(404).json({ error: 'Item not found' });
  }

  const deleted = items.splice(index, 1)[0];
  res.json({ message: 'Item deleted', item: deleted });
});

app.listen(PORT, () => {
  console.log(`Test API running at http://localhost:${PORT}`);
  console.log('Available endpoints:');
  console.log('  GET    /health        - Health check');
  console.log('  GET    /api/items     - List all items');
  console.log('  GET    /api/items/:id - Get item by ID');
  console.log('  POST   /api/items     - Create item');
  console.log('  PUT    /api/items/:id - Update item');
  console.log('  DELETE /api/items/:id - Delete item');
});
```

Now I'll start the server in the background and test it:

```bash
cd /home/jack/Coding/Rust/cuttlefish-rs/test-api && node server.js &
sleep 2
echo "--- Testing endpoints ---"
echo ""
echo "1. Health check:"
curl -s http://localhost:3000/health | head -c 200
echo ""
echo ""
echo "2. List all items:"
curl -s http://localhost:3000/api/items | head -c 300
echo ""
echo ""
echo "3. Get single item:"
curl -s http://localhost:3000/api/items/1 | head -c 200
echo ""
echo ""
echo "4. Create new item:"
curl -s -X POST http://localhost:3000/api/items -H "Content-Type: application/json" -d '{"name":"Item Three","description":"Created via API"}' | head -c 200
echo ""
echo ""
echo "5. List items after creation:"
curl -s http://localhost:3000/api/items | head -c 400
```

